import { Hatchet } from '@hatchet-dev/typescript-sdk';
import fs from 'fs';

const runId = process.env.ZEALT_RUN_ID;
if (!runId) {
  console.error('ZEALT_RUN_ID environment variable is not set');
  process.exit(1);
}

const hatchet = Hatchet.init();

const childWorkflow = hatchet.workflow({
  id: `square-item-${runId}`,
  on: { event: `child:create-${runId}` },
  steps: [
    {
      name: `square-step-${runId}`,
      run: async (ctx) => {
        const { n } = ctx.workflowInput() as { n: number };
        console.log(`Squaring ${n}`);
        return { square: n * n };
      },
    },
  ],
});

const parentWorkflow = hatchet.workflow({
  id: `process-batch-${runId}`,
  on: { event: `parent:create-${runId}` },
  steps: [
    {
      name: `process-step-${runId}`,
      run: async (ctx) => {
        const { items } = ctx.workflowInput() as { items: number[] };
        console.log(`Processing items: ${items}`);
        const promises = items.map((n: number) =>
          ctx.spawnWorkflow(`square-item-${runId}`, { n }).result()
        );
        const results = await Promise.all(promises);
        return { squares: results.map((r: any) => r.square) };
      },
    },
  ],
});

async function main() {
  const worker = await hatchet.worker('batch-worker');
  await worker.registerWorkflow(childWorkflow);
  await worker.registerWorkflow(parentWorkflow);

  console.log('Starting worker...');
  const stopWorker = await worker.start();

  try {
    console.log('Triggering parent workflow...');
    const workflowRun = await hatchet.admin.runWorkflow(`process-batch-${runId}`, {
      items: [1, 2, 3, 4, 5],
    });

    console.log('Waiting for result...');
    const result = await workflowRun.result();
    console.log('Result received:', result);

    fs.writeFileSync('/tmp/result.json', JSON.stringify(result));
    console.log('Result written to /tmp/result.json');
  } catch (e) {
    console.error('Error during workflow execution:', e);
    process.exit(1);
  } finally {
    console.log('Stopping worker...');
    await stopWorker();
    process.exit(0);
  }
}

main().catch((err) => {
  console.error('Unhandled error in main:', err);
  process.exit(1);
});

